{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "Salmeterol, the closest analogue (Morgan 0.678) sharing the same phenylethanolamine core and long aminoalkyl ether chain, has an oral bioavailability of about 1% in patients, affirmatively supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Salbutamol, which shares the hydroxymethyl-phenol ethanolamine core but has a much shorter tert-butylamino substituent, shows absolute oral bioavailability of 44% in healthy volunteers; this is contradictory evidence for high F but has lower transferability to the long-chain query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The closest high-similarity analogue salmeterol has ~1% oral bioavailability, and the query shares the same core and long aminoalkyl ether chain; although salbutamol shows higher F, its much shorter N-substituent makes it less transferable. Overall evidence supports F <20%.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "Effect of replacing the phenylbutyl tail with a dichlorobenzyl-ethoxy-ethoxy group on absorption and first-pass metabolism is unknown.",
    "Salmeterol evidence is from patients with COPD/asthma and the bioavailability report type is unspecified."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

